### Command Palette (Cmd+K)

```javascript
document.addEventListener('keydown', (e) => {
    if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        toggleCmd();
    }
});

const CMD_ITEMS = [
    { id: 'dashboard', label: 'Go to Dashboard', desc: 'View gateway overview', icon: '⌂' },
    { id: 'models', label: 'Manage Models', desc: 'View, add, edit, or remove models', icon: '⚙' },
    { id: 'playground', label: 'Open Playground', desc: 'Test models with chat', icon: '💬' },
    { id: 'settings', label: 'Settings', desc: 'Configure gateway', icon: '⚒' },
