### Empty state pattern

```html
<div class="empty-state">
    <div class="empty-icon">🤖</div>
    <div class="empty-title">No models configured</div>
    <div class="empty-desc">Add your first model or import from a provider preset to get started.</div>
    <div style="display:flex;gap:8px;justify-content:center">
        <button class="btn btn-primary" onclick="showAddModel()">+ Add Model</button>
        <button class="btn btn-secondary" onclick="showImportModal()">Import Preset</button>
    </div>
</div>
```

### Model card grid (when models exist)

```javascript
function renderModels() {
    if (state.models.length === 0) return renderEmptyState();
    return '<div class="model-grid">' +
        state.models.map(m => '<div class="model-card">' +
            '<div class="model-card-header">' +
            '<span class="model-provider-badge">' + m.provider + '</span>' +
            '<button class="btn-icon" onclick="removeModel(\\'' + m.id + '\\')">×</button>' +
            '</div>' +
            '<div class="model-name">' + m.name + '</div>' +
            '<div class="model-id">' + m.id + '</div>' +
            '<div class="model-card-footer">' +
            '<span class="status-dot online"></span> Ready' +
            '</div>' +
            '</div>'
        ).join('') + '</div>';
}
```

### API call pattern with auth (fetch from SPA)

When the Go gateway uses Bearer-key auth middleware on API routes, the SPA must send auth headers. Use a wrapper function that reads from localStorage:

```javascript
// ── Auth ────────────────────────────────────────────────────
function getApiKey() {
  return localStorage.getItem('gateway_api_key') || '';
}
function setApiKey(key) {
  localStorage.setItem('gateway_api_key', key);
}
function hasApiKey() {
  return !!getApiKey();
}

// ── API wrapper with auth ──────────────────────────────────
async function api(url, opts) {
  opts = opts || {};
  opts.headers = opts.headers || {};
  opts.headers['Content-Type'] = 'application/json';
  const key = getApiKey();
  if (key) opts.headers['Authorization'] = 'Bearer ' + key;
  try {
    const r = await fetch(url, opts);
    if (!r.ok) {
      const text = await r.text().catch(() => '');
      throw new Error(text || 'HTTP ' + r.status);
    }
    return r.headers.get('content-type') && r.headers.get('content-type').includes('json') ? r.json() : r.text();
  } catch (e) {
    toast(e.message, 'error');
    throw e;
  }
}

async function loadModels() {
    const data = await api('/v1/models');
    state.models = data.data || data.models || data || [];
    render();
}

async function addModel() {
    const model = {
        name: document.getElementById('modelName').value,
        provider: document.getElementById('modelProvider').value,
        id: document.getElementById('modelId').value,
        base_url: document.getElementById('modelBaseUrl').value,
        api_key: document.getElementById('modelApiKey').value,
    };
    await api('/v1/models', {
        method: 'POST',
        body: JSON.stringify(model),
    });
    closeModal();
    await loadModels();
}
```

### Setup screen pattern (API key prompt)

When no API key is stored, show a setup screen before the main UI. The `render()` function checks `hasApiKey()` first:

```javascript
function render() {
  const app = document.getElementById('app');
  if (!app) return;

  // If no API key is stored, show setup screen
  if (!hasApiKey()) {
    app.innerHTML = renderSetup();
    return;
  }

  // ... normal render logic
}

function renderSetup() {
  return '<div class="setup-overlay">' +
    '<div class="setup-card">' +
      '<div class="setup-logo">O</div>' +
      '<h1 class="setup-title">Gateway Name</h1>' +
      '<p class="setup-desc">Enter your API key to connect.</p>' +
      '<div class="setup-form">' +
        '<div class="input-group">' +
          '<label class="input-label">API Key</label>' +
          '<input class="input" id="setup-key" type="password" placeholder="Enter your API key..." autofocus>' +
        '</div>' +
        '<button class="btn btn-primary setup-btn" onclick="connectGateway()">Connect</button>' +
      '</div>' +
      '<p class="setup-hint">Default key: <code>test-key</code></p>' +
    '</div>' +
  '</div>';
}

async function connectGateway() {
  const key = document.getElementById('setup-key').value.trim();
  if (!key) { toast('Please enter an API key', 'error'); return; }
  setApiKey(key);
  try {
    await loadModels();  // validates key AND populates state.models
    toast('Connected successfully', 'success');
    STATE.loading = false;
    render();
  } catch (e) {
    setApiKey('');  // clear invalid key
